{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table eggozdb.maplemonk.pp_box as select tt.date,beat_name, area, loading_point, avg(pp_box_in) pp_box_in, avg(pp_box_out) pp_box_out, avg(cbb_box_in) cbb_box_in, avg(cbb_box_out) cbb_box_out, sum(out) out, sum(out_eggs) out_eggs from (select t1.date, t1.region as \"Procurement_Region\", t2.pp_box_out,t2.pp_box_in, t2.cbb_box_in,t2.cbb_box_out, t2.beat_number, t2.beat_name, t2.area, t2.beat_status, t2.beat_material_status, t2.supply_approval_status, t2.Short, t2.Short_eggs, t2.Fresh_Short, t2.Fresh_Short_Eggs, t2.Old_Short, t2.Old_Short_Eggs, t2.jse, t2.loading_point, t2.sku_count, t2.sku, t2.short_name, t2.zone_name, t2.name, ifnull(t2.demand,0) demand, ifnull(t2.out,0) out, ifnull(t2.sold,0) sold, ifnull(t2.promo,0) promo, ifnull(t2.damage,0) damage, ifnull(t2.old_damage,0) old_damage, ifnull(t2.logistics_fresh_missing,0) logistics_fresh_missing, ifnull(t2.logistics_old_missing,0) logistics_old_missing, t2.in_remarks, t2.in_old_remarks, ifnull(t2.return,0) return, ifnull(t2.supply,0) supply, ifnull(t2.fresh_in,0) fresh_in, ifnull(t2.transfer,0) transfer, ifnull(t2.replacement,0) replacement, ifnull(t2.old_in,0) old_in, ifnull(t2.logistics_fresh_missing_eggs,0) logistics_fresh_missing_eggs, ifnull(t2.logistics_old_missing_eggs,0) logistics_old_missing_eggs, ifnull(t2.demand_eggs,0) demand_eggs, ifnull(t2.out_eggs,0) out_eggs, ifnull(t2.sold_eggs,0) sold_eggs, ifnull(t2.replacement_eggs,0) replacement_eggs, ifnull(t2.return_eggs,0) return_eggs, ifnull(t2.fresh_in_eggs,0) fresh_in_eggs, ifnull(t2.damage_eggs,0) damage_eggs, ifnull(t2.old_damage_eggs,0) old_damage_eggs, ifnull(t2.promo_eggs,0) promo_eggs, ifnull(t2.supply_eggs,0) supply_eggs, ifnull(t2.transfer_eggs,0) transfer_eggs, ifnull(t2.old_in_eggs,0) old_in_eggs from (select date::date date, region from eggozdb.maplemonk.date_region_dim where region <> \'U.P\') t1 left join ( select b.beat_number beat_number ,b.beat_name beat_name ,cast(timestampadd(minute,330,dateadd(hour, 5.5, b.beat_date)) as date) AS date ,b.demand_classification area ,b.beat_status, b.beat_material_status, b.supply_approval_status ,CASE WHEN b.demand_classification IN (\'Gurgaon-GT\',\'Delhi-GT\',\'NCR-OF-MT\',\'Noida-GT\',\'NCR-MT\',\'NCR-ON-MT\',\'NCR-HORECA\',\'Allahabad-GT\',\'Lucknow-GT\', \'UP-MT\',\'UP-ON-MT\',\'UP-OF-MT\',\'Indore-GT\',\'Bhopal-GT\',\'MP-ON-MT\',\'MP-OF-MT\',\'Chandigarh-GT\', \'Chandigarh-ON-MT\',\'Chandigarh-OF-MT\', \'Mumbai-ON-MT\',\'Jaipur-GT\',\'NCR-GT\',\'Punjab-ON-MT\',\'Jaipur-OF-MT\',\'Jaipur-ON-MT\' ) THEN \'NCR\' WHEN b.demand_classification IN(\'Bangalore-Horeca\',\'Bangalore-MT\',\'Bangalore-GT\',\'Bangalore-ON-MT\',\'Bangalore-OF-MT\',\'Chennai-ON-MT\',\'Chennai-OF-MT\' ) THEN \'Bangalore\' WHEN b.demand_classification LIKE \'Hyderabad%\' THEN \'Hyderabad\' WHEN b.demand_classification LIKE \'Pune-ON-MT%\' THEN \'Hyderabad\' WHEN b.demand_classification IN (\'East-MT\',\'East-ON-MT\', \'East-OF-MT\', \'Patna-GT\',\'Kolkata-GT\',\'D2C\') THEN \'NCR\' ELSE \'Others\' END AS \"Procurement_Region\" ,cau.name jse ,ww.name as loading_point ,pp.sku_count ,concat(pp.sku_count,pp.short_name) sku ,pp.name ,pp.short_name ,bz.zone_name ,in_remarks ,in_old_remarks, sum(pp_box_in)AS pp_box_in, sum(pp_box_out)as pp_box_out, sum(cbb_box_in) as cbb_box_in, sum(cbb_box_out) as cbb_box_out ,sum(product_quantity) demand ,sum(product_out_quantity) out ,sum(product_sold_quantity) sold ,sum(product_promo_quantity) promo ,sum(product_damage_quantity) damage ,sum(product_old_damage_quantity) old_damage ,sum(product_logistics_fresh_missing_quantity) logistics_fresh_missing ,sum(product_logistics_old_missing_quantity) logistics_old_missing ,sum(product_return_quantity) return ,sum(product_supply_quantity) supply ,sum(product_fresh_in_quantity) fresh_in ,sum(product_transfer_quantity) transfer ,sum(product_replacement_quantity) replacement ,sum(product_return_replace_in_quantity) old_in ,sum(product_logistics_fresh_missing_quantity)*pp.sku_count logistics_fresh_missing_eggs ,sum(product_logistics_old_missing_quantity)*pp.sku_count logistics_old_missing_eggs ,sum(product_quantity)*pp.sku_count demand_eggs ,sum(product_out_quantity)*pp.sku_count out_eggs ,sum(product_sold_quantity)*pp.sku_count sold_eggs ,sum(product_replacement_quantity)*pp.sku_count replacement_eggs ,sum(product_return_quantity)*pp.sku_count return_eggs ,sum(product_fresh_in_quantity)*pp.sku_count fresh_in_eggs ,sum(product_damage_quantity)*pp.sku_count damage_eggs ,sum(product_old_damage_quantity)*pp.sku_count old_damage_eggs ,sum(product_promo_quantity)*pp.sku_count promo_eggs ,sum(product_supply_quantity)*pp.sku_count supply_eggs ,sum(product_transfer_quantity)*pp.sku_count transfer_eggs ,sum(product_return_replace_in_quantity)*pp.sku_count old_in_eggs ,(out+transfer-sold+return-promo-fresh_in-old_in-damage-old_damage-logistics_fresh_missing-logistics_old_missing) as Short ,(out_eggs+transfer_eggs-sold_eggs+return_eggs-promo_eggs-fresh_in_eggs-old_in_eggs-damage_eggs-old_damage_eggs-logistics_fresh_missing_eggs-logistics_old_missing_eggs) as Short_eggs ,(out+transfer-sold-replacement-promo-fresh_in-damage) as Fresh_Short ,(out_eggs+transfer_eggs-sold_eggs-replacement_eggs-promo_eggs-fresh_in_eggs-damage_eggs) as Fresh_Short_Eggs ,(return+replacement-old_damage-old_in) as Old_Short ,(return_eggs+replacement_eggs-old_damage_eggs-old_in_eggs) as Old_Short_Eggs from eggozdb.maplemonk.my_sql_saleschain_salesdemandsku s left join eggozdb.maplemonk.my_sql_distributionchain_beatassignment b on s.beatassignment_id = b.id left join eggozdb.maplemonk.my_sql_warehouse_warehouse ww on ww.id = b.warehouse_id left join eggozdb.maplemonk.my_sql_base_zone bz on bz.id = ww.zone_id left join eggozdb.maplemonk.my_sql_product_product pp on pp.id = s.product_id left join eggozdb.maplemonk.my_sql_saleschain_salespersonprofile d on d.id = b.jse_id LEFT JOIN eggozdb.Maplemonk.my_sql_custom_auth_user cau ON cau.id = d.user_id where lower(b.supply_approval_status)<>\'cancelled\' and lower(pp.slug) not like \'%djn%\' group by b.beat_number ,b.beat_name ,b.beat_material_status ,b.supply_approval_status ,date ,s.in_remarks ,s.in_old_remarks ,b.demand_classification ,b.beat_status ,cau.name ,pp.sku_count ,concat(pp.sku_count,pp.name) ,pp.short_name ,ww.name ,pp.name ,bz.zone_name ) t2 on t1.date = t2.date and t1.region = t2.\"Procurement_Region\")tt group by tt.date,tt.beat_name,tt.area,tt.loading_point ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

